fn replace(arr: &mut Vec<i32>, k: i32) {
    // Iterate over every element in the vector by mutable reference.
    for x in arr.iter_mut() {
        // If the original value is strictly greater than k, set it to -1,
        // otherwise leave it unchanged.
        if *x > k {
            *x = -1;
        }
    }
}

fn main() {
    let mut v1 = vec![1, 5, 3, 7, 2];
    replace(&mut v1, 4);
    assert_eq!(v1, vec![1, -1, 3, -1, 2]);

    let mut v2: Vec<i32> = vec![];
    replace(&mut v2, 10);
    assert_eq!(v2, vec![]);

    let mut v3 = vec![0, -5, 10, 10, 11];
    replace(&mut v3, 10);
    assert_eq!(v3, vec![0, -5, 10, 10, -1]);

    println!("All tests passed!");
}